 73	/// to keep track of any state or if its already been freed.
 74	thread_enter_state: ?*ThreadEnterState = null,
 75	
 76	/// The state we need to keep around only until we enter the IO
 77	/// thread. Then we can throw it all away.
 78	const ThreadEnterState = struct {
 79	    arena: ArenaAllocator,
 80	
 81	    /// Initial input to send to the subprocess after starting. This
 82	    /// memory is freed once the subprocess start is attempted, even
 83	    /// if it fails, because Exec only starts once.
 84	    input: configpkg.io.RepeatableReadableIO,
 85	
 86	    pub fn create(
 87	        alloc: Allocator,
 88	        config: *const configpkg.Config,
 89	    ) !?*ThreadEnterState {
 90	        // If we have no input then we have no thread enter state
 91	        if (config.input.list.items.len == 0) return null;
 92	
 93	        // Create our arena allocator
 94	        var arena = ArenaAllocator.init(alloc);
 95	        errdefer arena.deinit();
 96	        const arena_alloc = arena.allocator();
 97	
 98	        // Allocate our ThreadEnterState
 99	        const ptr = try arena_alloc.create(ThreadEnterState);
100	
101	        // Copy the input from the config
102	        const input = try config.input.cloneParsed(arena_alloc);
103	
104	        // Return the initialized state
105	        ptr.* = .{
106	            .arena = arena,
107	            .input = input,
108	        };
109	        return ptr;
110	    }
111	
112	    pub fn destroy(self: *ThreadEnterState) void {
113	        self.arena.deinit();
114	    }
115	
116	    /// Prepare the inputs for use. Allocations happen on the arena.
117	    pub fn prepareInput(
118	        self: *ThreadEnterState,
119	    ) (Allocator.Error || error{InputNotFound})![]const Input {
120	        const alloc = self.arena.allocator();
121	
122	        var inputs: std.ArrayList(Input) = try .initCapacity(
123	            alloc,
124	            self.input.list.items.len,
125	        );
126	        errdefer for (inputs.items) |item| item.deinit();
127	
128	        for (self.input.list.items) |item| {
129	            inputs.appendAssumeCapacity(switch (item) {
130	                .raw => |v| .{ .string = v },
131	                .path => |path| file: {
132	                    const f = std.Io.Dir.cwd().openFile(
133	                        global.io(),
134	                        path,
135	                        .{},
136	                    ) catch |err| {
137	                        log.warn("failed to open input file={s} err={}", .{
138	                            path,
139	                            err,
140	                        });
141	                        return error.InputNotFound;
142	                    };
143	
144	                    break :file .{ .file = f };
145	                },
146	            });
147	        }
148	
149	        return inputs.items;
150	    }
151	
152	    const Input = union(enum) {
153	        string: []const u8,
154	        file: std.Io.File,
155	
156	        fn deinit(self: Input) void {
157	            switch (self) {
158	                .string => {},
159	                .file => |f| f.close(global.io()),
160	            }
161	        }
162	    };
163	};
