   408	fn syncResetCallback(
   409	    cb_: ?*CallbackData,
   410	    _: *xev.Loop,
   411	    _: *xev.Completion,
   412	    r: xev.Timer.RunError!void,
   413	) xev.CallbackAction {
   414	    _ = r catch |err| switch (err) {
   415	        error.Canceled => {},
   416	        else => {
   417	            log.warn("error during sync reset callback err={}", .{err});
   418	            return .disarm;
   419	        },
   420	    };
   421	
   422	    const cb = cb_ orelse return .disarm;
   423	    cb.io.resetSynchronizedOutput();
   424	    return .disarm;
   425	}
